<?php

declare(strict_types=1);
function normalize_image_urls(array $item):array{$urls=[];foreach(['mediumImageUrls','smallImageUrls'] as $key)foreach((array)($item[$key]??[]) as $image){$url=is_array($image)?(string)($image['imageUrl']??''):(string)$image;if($url!=='')$urls[$url]=true;}return array_slice(array_keys($urls),0,3);}function save_item(PDO $pdo,array $item):int{$images=normalize_image_urls($item);$image=$images[0]??null;$sql="INSERT INTO items (item_code,item_name,catchcopy,item_price,item_url,affiliate_url,image_url,shop_code,shop_name,shop_url,review_count,review_average,affiliate_rate,postage_flag,availability,genre_id,raw_json,last_seen_at) VALUES (:item_code,:item_name,:catchcopy,:item_price,:item_url,:affiliate_url,:image_url,:shop_code,:shop_name,:shop_url,:review_count,:review_average,:affiliate_rate,:postage_flag,:availability,:genre_id,:raw_json,NOW()) ON DUPLICATE KEY UPDATE item_name=VALUES(item_name),catchcopy=VALUES(catchcopy),item_price=VALUES(item_price),item_url=VALUES(item_url),affiliate_url=VALUES(affiliate_url),image_url=VALUES(image_url),shop_code=VALUES(shop_code),shop_name=VALUES(shop_name),shop_url=VALUES(shop_url),review_count=VALUES(review_count),review_average=VALUES(review_average),affiliate_rate=VALUES(affiliate_rate),postage_flag=VALUES(postage_flag),availability=VALUES(availability),genre_id=VALUES(genre_id),raw_json=VALUES(raw_json),last_seen_at=NOW(),id=LAST_INSERT_ID(id)";$pdo->prepare($sql)->execute([':item_code'=>(string)($item['itemCode']??''),':item_name'=>(string)($item['itemName']??''),':catchcopy'=>(string)($item['catchcopy']??''),':item_price'=>(int)($item['itemPrice']??0),':item_url'=>(string)($item['itemUrl']??''),':affiliate_url'=>(string)($item['affiliateUrl']??$item['itemUrl']??''),':image_url'=>$image,':shop_code'=>(string)($item['shopCode']??''),':shop_name'=>(string)($item['shopName']??''),':shop_url'=>(string)($item['shopAffiliateUrl']??$item['shopUrl']??''),':review_count'=>(int)($item['reviewCount']??0),':review_average'=>(float)($item['reviewAverage']??0),':affiliate_rate'=>(float)($item['affiliateRate']??0),':postage_flag'=>(int)($item['postageFlag']??0),':availability'=>(int)($item['availability']??1),':genre_id'=>isset($item['genreId'])?(int)$item['genreId']:null,':raw_json'=>json_encode($item,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)]);$id=(int)$pdo->lastInsertId();if($id>0){$pdo->prepare('DELETE FROM item_images WHERE item_id=?')->execute([$id]);$st=$pdo->prepare('INSERT INTO item_images(item_id,image_url,sort_order) VALUES(?,?,?)');foreach($images as $i=>$url)$st->execute([$id,$url,$i]);}return $id;}function search_items(PDO $pdo,array $filters,int $limit=30,int $offset=0):array{$where=['i.availability=1'];$params=[];if(($filters['q']??'')!==''){$where[]='(i.item_name LIKE :q OR i.catchcopy LIKE :q OR i.shop_name LIKE :q)';$params[':q']='%'.$filters['q'].'%';}if(($filters['min_price']??'')!==''){$where[]='i.item_price>=:min_price';$params[':min_price']=(int)$filters['min_price'];}if(($filters['max_price']??'')!==''){$where[]='i.item_price<=:max_price';$params[':max_price']=(int)$filters['max_price'];}if(($filters['min_review']??'')!==''){$where[]='i.review_average>=:min_review';$params[':min_review']=(float)$filters['min_review'];}if(!empty($filters['free_shipping']))$where[]='i.postage_flag=0';if(!empty($filters['category'])){$where[]='EXISTS(SELECT 1 FROM item_categories ic WHERE ic.item_id=i.id AND ic.category_id=:category)';$params[':category']=(int)$filters['category'];}if(!empty($filters['shop'])){$where[]='i.shop_code=:shop';$params[':shop']=(string)$filters['shop'];}$orders=['review'=>'i.review_average DESC,i.review_count DESC','reviews'=>'i.review_count DESC,i.review_average DESC','price_asc'=>'i.item_price ASC','price_desc'=>'i.item_price DESC','new'=>'i.first_seen_at DESC','popular'=>'views_30d DESC,i.review_count DESC'];$order=$orders[$filters['sort']??'popular']??$orders['popular'];$sql='SELECT i.*,(SELECT COUNT(*) FROM page_views pv WHERE pv.path=CONCAT("/item.php?id=",i.id) AND pv.created_at>=DATE_SUB(NOW(),INTERVAL 30 DAY)) views_30d FROM items i WHERE '.implode(' AND ',$where).' ORDER BY '.$order.' LIMIT :limit OFFSET :offset';$st=$pdo->prepare($sql);foreach($params as $k=>$v)$st->bindValue($k,$v);$st->bindValue(':limit',$limit,PDO::PARAM_INT);$st->bindValue(':offset',$offset,PDO::PARAM_INT);$st->execute();return $st->fetchAll();}function get_item(PDO $pdo,int $id):?array{$s=$pdo->prepare('SELECT * FROM items WHERE id=? AND availability=1 LIMIT 1');$s->execute([$id]);$r=$s->fetch();return $r?:null;}function get_item_images(PDO $pdo,int $id):array{$s=$pdo->prepare('SELECT image_url FROM item_images WHERE item_id=? ORDER BY sort_order');$s->execute([$id]);return array_column($s->fetchAll(),'image_url');}function categories(PDO $pdo):array{return $pdo->query('SELECT c.*,COUNT(ic.item_id) item_count FROM categories c LEFT JOIN item_categories ic ON ic.category_id=c.id WHERE c.is_active=1 GROUP BY c.id ORDER BY c.sort_order,c.name')->fetchAll();}function category_by_slug(PDO $pdo,string $slug):?array{$s=$pdo->prepare('SELECT * FROM categories WHERE slug=? AND is_active=1 LIMIT 1');$s->execute([$slug]);$r=$s->fetch();return $r?:null;}function related_items(PDO $pdo,array $item,int $limit=8):array{$s=$pdo->prepare('SELECT * FROM items WHERE availability=1 AND id<>? AND (genre_id=? OR shop_code=?) ORDER BY review_count DESC LIMIT '.$limit);$s->execute([(int)$item['id'],(int)$item['genre_id'],(string)$item['shop_code']]);return $s->fetchAll();}
